import hashlib

class Bloom:
    def __init__(self, m, k):
        self.bits = bytearray((m + 7) // 8)
        self.m, self.k = m, k
    def _pos(self, key, i):
        return int(hashlib.md5(('%d:%s' % (i, key)).encode()).hexdigest(), 16) % self.m
    def add(self, key):
        for i in range(self.k):
            p = self._pos(key, i)
            self.bits[p // 8] |= 1 << (p % 8)
    def __contains__(self, key):
        return all(self.bits[p // 8] >> (p % 8) & 1 for p in (self._pos(key, i) for i in range(self.k)))

bf = Bloom(m=1000, k=7)
for w in ['vector', 'index', 'search']:
    bf.add(w)
print('vector in set:', 'vector' in bf, '| index in set:', 'index' in bf)
print('absent "zzz":', 'zzz' in bf, '(maybe: false positives possible, never false negatives)')
print('missing key test:', 'definitely-not-here' in bf)

import hashlib

class CountingBloom:
    def __init__(self, m, k):
        self.c = [0] * m
        self.m, self.k = m, k
    def _pos(self, key, i):
        return int(hashlib.md5(('%d:%s' % (i, key)).encode()).hexdigest(), 16) % self.m
    def add(self, key):
        for i in range(self.k):
            self.c[self._pos(key, i)] = min(15, self.c[self._pos(key, i)] + 1)
    def remove(self, key):
        if key in self:
            for i in range(self.k):
                self.c[self._pos(key, i)] -= 1
    def __contains__(self, key):
        return all(self.c[self._pos(key, i)] > 0 for i in range(self.k))

cb = CountingBloom(500, 5)
cb.add('session:1'); cb.add('session:2')
print('before remove:', 'session:1' in cb)
cb.remove('session:1')
print('after remove :', 'session:1' in cb, '(deletion works; classic Bloom cannot do this)')

# scalable Bloom: chain filters, each 2x bigger; FP stays bounded as n grows
import math

class Chain:
    def __init__(self):
        self.filters = [set()]  # sets stand in for Bloom filters here
        self.cap = [100]
    def add(self, x):
        if len(self.filters[-1]) >= self.cap[-1]:
            self.filters.append(set())
            self.cap.append(self.cap[-1] * 2)
        self.filters[-1].add(x)
    def __contains__(self, x):
        return any(x in f for f in self.filters)

c = Chain()
for i in range(350):
    c.add('k%d' % i)
print('elements: 350 | filters in chain:', len(c.filters), '| capacities:', c.cap)
print('lookup k7:', 'k7' in c, '| lookup missing:', 'k9999' in c)
print('unbounded growth, bounded FP: add a bigger filter when full')

import hashlib, random
random.seed(8)

class Cuckoo:
    def __init__(self, buckets=64, slots=4):
        self.t = [[None] * slots for _ in range(buckets)]
        self.n = buckets
    def _fp(self, k):
        return hashlib.md5(k.encode()).digest()[0] or 1
    def _b(self, k):
        return int(hashlib.md5(k.encode()).hexdigest(), 16) % self.n
    def _alt(self, b, fp):
        return (b ^ (fp * 0x5bd1e995)) % self.n
    def add(self, k):
        fp, b = self._fp(k), self._b(k)
        for _ in range(8):
            for bucket in (b, self._alt(b, fp)):
                if None in self.t[bucket]:
                    self.t[bucket][self.t[bucket].index(None)] = fp
                    return True
            b = self._alt(b, fp)  # kick a random occupant along
            i = random.randrange(len(self.t[b]))
            fp, self.t[b][i] = self.t[b][i], fp
        return False
    def __contains__(self, k):
        fp, b = self._fp(k), self._b(k)
        return fp in self.t[b] or fp in self.t[self._alt(b, fp)]
    def remove(self, k):
        fp, b = self._fp(k), self._b(k)
        for bucket in (b, self._alt(b, fp)):
            if fp in self.t[bucket]:
                self.t[bucket][self.t[bucket].index(fp)] = None
                return True
        return False

cf = Cuckoo()
for w in ['alpha', 'beta', 'gamma']:
    cf.add(w)
print('beta present:', 'beta' in cf)
cf.remove('beta')
print('after remove:', 'beta' in cf, '| alpha still:', 'alpha' in cf)

# quotient filter idea: quotient picks the bucket, remainder is stored.
import hashlib
Q = 8  # 2^3 buckets
table = {}

def split(key):
    h = int(hashlib.md5(key.encode()).hexdigest(), 16)
    return h >> (128 - 3), h & 0xFF  # quotient (bucket), remainder (fingerprint)

for k in ['apple', 'banana', 'cherry']:
    q, r = split(k)
    table.setdefault(q, []).append(r)  # collisions chain in the bucket
    print('%-7s -> bucket %d, stored remainder 0x%02x' % (k, q, r))

q, r = split('banana')
print('lookup banana: remainder 0x%02x in bucket %d ->' % (r, q), r in table.get(q, []))

# per-SSTable Bloom filters: skip SSTables that cannot contain the key
import hashlib

class TinyBF:
    def __init__(self, keys):
        self.s = set()
        for k in keys:
            self.s.add(hashlib.md5(k.encode()).hexdigest()[:6])  # fingerprint set
    def maybe(self, k):
        return hashlib.md5(k.encode()).hexdigest()[:6] in self.s

sstables = [
    {'keys': ['k1', 'k2'], 'bf': None},
    {'keys': ['k3', 'k4'], 'bf': None},
    {'keys': ['k5', 'k6'], 'bf': None},
]
for s in sstables:
    s['bf'] = TinyBF(s['keys'])

def point_lookup(key):
    opened = 0
    for s in sstables:
        if s['bf'].maybe(key):
            opened += 1
            if key in s['keys']:
                return 'found', opened
    return 'not found', opened

print('lookup k4:', point_lookup('k4'), '(opened 1 SSTable, skipped 2)')
print('lookup zz:', point_lookup('zz'), '(no SSTable opened at all)')

# blocked Bloom: one hash picks the 512-bit block; k bits live inside it.
import hashlib
BLOCKS, BITS = 8, 512
blocks = [[0] * (BITS // 64) for _ in range(BLOCKS)]

def positions(key, k=4):
    h = int(hashlib.md5(key.encode()).hexdigest(), 16)
    block = h % BLOCKS
    return block, [((h >> (i * 9)) % BITS) for i in range(1, k + 1)]

def add(key):
    b, ps = positions(key)
    for p in ps:
        blocks[b][p // 64] |= 1 << (p % 64)

def contains(key):
    b, ps = positions(key)
    return all(blocks[b][p // 64] >> (p % 64) & 1 for p in ps)

for w in ['alpha', 'beta']:
    add(w)
print('alpha:', contains('alpha'), '| missing:', contains('zzz'))
print('each query touches exactly ONE block (one cache line)')

def choose(static, need_delete, need_merge, fp_ok):
    if not fp_ok:
        return 'hash set (exact; FP must be 0)'
    if need_merge:
        return 'quotient filter (mergeable)'
    if need_delete:
        return 'cuckoo / counting Bloom (deletable)'
    if static:
        return 'XOR filter (fastest, smallest for static sets)'
    return 'classic Bloom (simplest dynamic)'

cases = [(True, False, False, True), (False, True, False, True),
         (False, False, True, True), (True, False, False, False)]
for c in cases:
    print('static=%s delete=%s merge=%s fp_ok=%s -> %s' % (*c, choose(*c)))

import struct, hashlib

def build(keys, m=256, k=3):
    bits = bytearray((m + 7) // 8)
    for key in keys:
        for i in range(k):
            p = int(hashlib.md5(('%d:%s' % (i, key)).encode()).hexdigest(), 16) % m
            bits[p // 8] |= 1 << (p % 8)
    header = struct.pack('>4sHHI', b'BLMF', 1, m, k)  # magic, version, m, k
    return header + bytes(bits)

blob = build(['a', 'b', 'c'])
magic, ver, m, k = struct.unpack('>4sHHI', blob[:12])
print('magic=%s version=%d m=%d k=%d body=%d bytes' % (magic, ver, m, k, len(blob) - 12))
print('mmap this region on open: zero-copy filter, no rebuild after restart')

import hashlib, random
random.seed(30)

class BF:
    def __init__(self, m, k):
        self.b = bytearray((m + 7) // 8); self.m, self.k = m, k
    def _p(self, x, i):
        return int(hashlib.md5(('%d:%s' % (i, x)).encode()).hexdigest(), 16) % self.m
    def add(self, x):
        for i in range(self.k):
            p = self._p(x, i); self.b[p // 8] |= 1 << (p % 8)
    def __contains__(self, x):
        return all(self.b[self._p(x, i) // 8] >> (self._p(x, i) % 8) & 1 for i in range(self.k))

inserted = ['user:%d' % i for i in range(5000)]
heldout = ['user:%d' % i for i in range(5000, 8000)]
bf = BF(m=50000, k=7)
for k in inserted:
    bf.add(k)
fp = sum(1 for k in heldout if k in bf) / len(heldout)
print('target ~1%%, measured FP: %.2f%% on real keys' % (fp * 100))
print('theory guides, measurement decides: re-check when key distribution shifts')
